package com.booksyde.mapper; import com.booksyde.dto.response.BookResponse; import com.booksyde.entity.MangaEntity; public final class BookMapper {private BookMapper(){} public static BookResponse toResponse(MangaEntity e){return new BookResponse(e.getId(),e.getTitle(),e.getAuthor(),e.getCategory(),e.getDescription(),e.getSynopsis(),e.getWorkType(),e.getCreatorId(),e.getSlug(),e.getVisibility(),e.getStatus(),e.isCollection(),e.getCoverUrl(),e.getPriceCents(),e.getCurrency(),e.getDistributionChannel(),e.getViewCount(),e.getCreatedAt());}}